<script setup>
import { ref, watch } from 'vue'
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const quantity = ref(1)
const activeSection = ref('details')
const localize = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const searchChanged = (event) => emit('update:searchQuery', event.target.value)
const buyNow = () => {
  if (!props.product) return
  emit('add-to-cart', props.product.id, quantity.value)
  emit('open-cart')
}
watch(() => props.product?.id, () => {
  quantity.value = 1
  activeSection.value = 'details'
})
</script>

<template>
  <main class="coupang-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
    <header class="cp-bar">
      <button type="button" aria-label="返回" @click="emit('back')"><i class="fas fa-chevron-left"></i></button>
      <strong>coupang</strong>
      <div><button type="button" aria-label="订单" @click="emit('open-orders')"><i class="fas fa-receipt"></i></button><button type="button" data-testid="shopping-page-cart" :aria-label="localize('购物车', 'Cart')" @click="emit('open-cart')"><i class="fas fa-cart-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div>
    </header>

    <template v-if="pageKey === 'category'">
      <section class="cp-search-zone">
        <p>{{ localize('现在需要什么？', 'What do you need now?') }}</p>
        <form @submit.prevent="emit('submit-search')"><i class="fas fa-magnifying-glass"></i><input type="search" :value="searchQuery" :placeholder="localize('搜索商品、品牌和关键词', 'Search products, brands, and keywords')" @input="searchChanged" /><button type="submit">{{ localize('搜索', 'Search') }}</button></form>
        <div class="cp-delivery-promise"><i class="fas fa-bolt"></i><div><strong>{{ localize('配送时段清晰可见', 'Clear delivery windows') }}</strong><span>{{ localize('可用时间、运费与路线将在结算前确认', 'Timing, cost, and route are confirmed before checkout') }}</span></div><em>SEOUL</em></div>
      </section>
      <nav class="cp-categories"><button v-for="item in categories" :key="item.key" type="button" :class="{active:item.key===category?.key}" @click="emit('select-category', item.key)"><i :class="item.icon"></i><span>{{ item.label }}</span><small>{{ item.count }}</small></button></nav>
      <section class="cp-results-head"><div><p>{{ category?.label || localize('全部商品', 'All products') }}</p><strong>{{ totalCount }} {{ localize('件商品', 'items') }}</strong></div><span>{{ localize('按当前分类显示', 'Current category') }}</span></section>
      <section class="cp-list">
        <article v-for="product in products" :key="product.id" :data-testid="`shopping-product-${product.id}`">
          <button type="button" class="cp-thumb" @click="emit('open-product', product.id)"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><i v-else :class="productCategoryIcon(product)"></i><span>ROCKET</span></button>
          <div class="cp-copy"><button type="button" class="cp-title" @click="emit('open-product', product.id)"><small>{{ serviceLabel }}</small><strong>{{ productDisplayTitle(product) }}</strong></button><p>{{ productDisplayDescription(product) }}</p><div class="cp-arrival"><i class="fas fa-bolt"></i>{{ localize('结算前确认配送时段', 'Delivery window at checkout') }}</div><footer><strong>{{ formatPrice(product) }}</strong><button type="button" :disabled="product.stockStatus==='sold_out'" @click="emit('add-to-cart', product.id)">{{ localize('加入购物车', 'Add') }}</button></footer></div>
        </article>
      </section>
      <nav v-if="pageCount>1" class="cp-pagination" data-testid="shopping-pagination"><button type="button" :disabled="page<=1" @click="emit('change-page',page-1)">PREV</button><span>{{ page }} / {{ pageCount }}</span><button type="button" :disabled="page>=pageCount" @click="emit('change-page',page+1)">NEXT</button></nav>
    </template>

    <template v-else-if="product">
      <section class="cp-pdp-main">
        <div class="cp-pdp-media"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><div v-else><i :class="productCategoryIcon(product)"></i><span>ROCKET ITEM</span></div></div>
        <div class="cp-pdp-buy"><p>COUPANG / CITY MARKET</p><h1>{{ productDisplayTitle(product) }}</h1><button type="button" class="cp-review-link" @click="activeSection='reviews'"><i class="far fa-star"></i>{{ localize('暂无评价 · 查看评价规则', 'No reviews yet · Review policy') }}</button><strong class="cp-price">{{ formatPrice(product) }}</strong><div class="cp-eta"><i class="fas fa-truck-fast"></i><div><strong>{{ localize('结算前确认到货时间', 'Confirm arrival before placing the order') }}</strong><span>{{ localize('运费、可追踪状态和售后资格以订单确认页为准', 'Delivery cost, tracking, and after-sales eligibility appear in review') }}</span></div></div><p class="cp-desc">{{ productDisplayDescription(product) }}</p><div class="cp-qty"><button type="button" :aria-label="localize('减少数量','Decrease quantity')" @click="quantity=Math.max(1,quantity-1)">−</button><strong>{{ quantity }}</strong><button type="button" :aria-label="localize('增加数量','Increase quantity')" @click="quantity=Math.min(99,quantity+1)">+</button></div><div class="cp-actions"><button type="button" :aria-label="localize('收藏商品','Save product')" :class="{saved:isProductFavorite(product.id)}" @click="emit('toggle-favorite',product.id)"><i class="fas fa-heart"></i></button><button type="button" data-testid="shopping-product-add" @click="emit('add-to-cart',product.id,quantity)">{{ localize('加入购物车', 'Add to cart') }}</button><button type="button" @click="buyNow">{{ localize('立即购买', 'Buy now') }}</button></div></div>
      </section>
      <section class="cp-pdp-info"><nav aria-label="Product information"><button type="button" :class="{active:activeSection==='details'}" @click="activeSection='details'">{{ localize('商品信息', 'Details') }}</button><button type="button" :class="{active:activeSection==='reviews'}" @click="activeSection='reviews'">{{ localize('评价', 'Reviews') }}</button><button type="button" :class="{active:activeSection==='delivery'}" @click="activeSection='delivery'">{{ localize('配送售后', 'Delivery') }}</button></nav><div v-if="activeSection==='details'" class="cp-info-panel"><article><span>01</span><div><h2>{{ localize('商品概览', 'Product overview') }}</h2><p>{{ productDisplayDescription(product) }}</p></div></article><article><span>02</span><div><h2>{{ localize('库存与包装', 'Stock and packaging') }}</h2><p>{{ localize(`当前状态：${stockStatusLabel(product.stockStatus)}。数量与最终包装以订单确认页为准。`, `Current status: ${stockStatusLabel(product.stockStatus)}. Final quantity and packaging appear in review.`) }}</p></div></article></div><div v-else-if="activeSection==='reviews'" class="cp-review-empty"><i class="far fa-comment-dots"></i><h2>{{ localize('还没有购买者评价', 'No buyer reviews yet') }}</h2><p>{{ localize('完成订单后，评价会按评分、购买规格、使用时间与实拍内容统一展示。', 'Completed buyers can leave a rating, purchased option, usage period, and photos in one consistent review format.') }}</p></div><div v-else class="cp-info-panel"><article><span>01</span><div><h2>{{ localize('配送确认', 'Delivery confirmation') }}</h2><p>{{ localize('可用时段、运费和承运信息会在创建订单前明确显示，不在商品页提前承诺。', 'Available timing, cost, and carrier information are shown before order creation rather than promised early.') }}</p></div></article><article><span>02</span><div><h2>{{ localize('取消与售后', 'Cancellation and after-sales') }}</h2><p>{{ localize('订单创建后，可在“我的订单”查看当前状态、物流节点与可用操作。', 'After purchase, My Orders shows status, tracking events, and currently available actions.') }}</p></div></article></div></section>
      <section class="cp-related"><h2>{{ localize('一起购买的商品', 'Frequently bought together') }}</h2><div><button v-for="item in relatedProducts.slice(0,4)" :key="item.id" type="button" @click="emit('open-product',item.id)"><span><img v-if="productImageUrl(item)" :src="productImageUrl(item)" :alt="productDisplayTitle(item)" /><i v-else :class="productCategoryIcon(item)"></i></span><strong>{{ productDisplayTitle(item) }}</strong><small>{{ formatPrice(item) }}</small></button></div></section>
    </template>
  </main>
</template>

